import{z as E,x as A,o as r,c as o,q as t,j as s,D as a,d as i,s as n,S as p}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Persistent kernel","description":"","frontmatter":{"title":"Persistent kernel","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/persistent-kernel.md","filePath":"llm/persistent-kernel.md","lastUpdated":1791063341000}'),B={name:"llm/persistent-kernel.md"};function d(h,e,C,c,m,M){const l=A("Mermaid");return r(),o("div",null,[e[2]||(e[2]=t('<h1 id="persistent-kernel" tabindex="-1">Persistent kernel <a class="header-anchor" href="#persistent-kernel" aria-label="Permalink to &quot;Persistent kernel&quot;">​</a></h1><div class="epigraph"><p>让 CTA 在 SM 上住下来，自己从设备侧队列取下一块工作，而不是每块 GEMM 由主机再 launch 一次：省掉的是核间排水与启动，不是单块内部的 MMA。</p><footer>—— NVIDIA CUTLASS 持久化调度 / CUDA 占用率模型，对照 Hopper 白皮书中的异步流水</footer></div><p><a href="/llm/wgmma">上一课</a>把 WGMMA 写成 4-warp 异步矩阵乘加：完成靠 commit/wait group，形状与 swizzle 是硬合同，小 \\(M\\) 的 decode 打不满阵列。缺口是短核密集时启动与排水：即使用 <a href="/llm/cuda-graph-infer">CUDA Graph</a> 把提交收成一次，相邻节点仍可能丢占用。Persistent kernel 把网格做成约占满 SM 的常驻 CTA，内层从工作队列取活。本课写何时该常驻、工作如何分发，不重写 wgmma 的形状合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 的吞吐建立在延迟隐藏上：足够多的 CTA / warp 在等内存时切出去做别的。核一结束，这些现场消失，下核再从零填指令缓存、记分牌和流水线。若每个核只做一小块工作（decode 的瘦 GEMM、一层里拆开的 RMSNorm），填满—排空的占空比变差。融合能把小核合成大核，但融合有数值与编译边界；Graph 能减 CPU 提交，但不保证 GPU 侧两个节点之间不断流。持久化要回答的是：能否让同一批 CTA 跨过「逻辑上的多个任务」保持占用。</p><p><span class="marginnote">术语翻译：CTA（线程块）是 GPU 上一起干活的一小组线程，SM 是真正执行它们的计算单元。「常驻」就是让这组线程一直占着 SM 不退出，做完一件工作再去设备队列领下一件，而不是干完就地解散。</span></p><p>代价同样真实。常驻 CTA 把 SM 占住，若队列短暂空闲，别的流上的核进不来，延迟尾部变差。工作分发若在设备上抢队列，原子争用会成为新瓶颈。问题是占用与公平、以及队列粒度，不是「常驻一定更快」。</p><h3 id="与-grid-stride-循环的差别" tabindex="-1">与 grid-stride 循环的差别 <a class="header-anchor" href="#与-grid-stride-循环的差别" aria-label="Permalink to &quot;与 grid-stride 循环的差别&quot;">​</a></h3><p>Grid-stride 是一个核内：CTA 用 <code>blockIdx + gridDim</code> 的步长扫完所有 tile，扫完核结束。它减少启动次数，但网格大小通常仍按 tile 数来，可能远超 SM 数，调度器靠过量 CTA 做切换。持久化把网格钉在「每 SM 一到数个 CTA」，循环条件是队列非空而不是「我的 stride 走完」。长时间驻留、跨多次逻辑 GEMM、甚至跨层，才是 persistent 这一词在 CUTLASS 与推理文献里的意思。二者都是「少启动」，粒度不同。</p><p><span class="marginnote">主机侧 <code>while</code> 里反复 launch 同一核，即使核很小，也不是持久化。持久化的判定是：设备上的 CTA 在一次 launch 里消费了多次逻辑工作项。Nsight Systems 上应看到一次很长的核，而不是一排同名短核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上通常有三件套。</p><p><strong>占用目标</strong>：grid 取 <code>sm_count × cta_per_sm</code>，<code>cta_per_sm</code> 由寄存器与 smem 反推，保证常驻而不过度超订。超订在持久化里帮助变小——反正 CTA 不退出，多余的 CTA 只是排队等 SM，浪费队列里的工作项编号。</p><p><strong>工作队列</strong>：可以是全局内存里的原子计数器（下一个 tile ID）、按层预排好的静态表、或 Hopper 上与 TMA 描述符列表结合的「下一盒子」。Stream-K 一类调度把 \\(K\\) 维切给不同 CTA 再规约，也常落在持久化 CTA 上：CTA 跑完自己的 K 片段后去取下一项，而不是结束核。</p><p><strong>退出条件</strong>：队列空、或主机写入的停止标志。推理 decode 可以把「一整步的所有层」放进一次持久核，层间不退 SM；也可以每层一个持久核，由 Graph 串起来。前者占用最好，但要把一整步的控制流写进同一核，MoE 与变长很难。后者更模块化，排水发生在层边界。</p>',15)),(r(),s(p,null,{default:a(()=>[n(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%B8%BB%E6%9C%BA%20launch%20%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20CTA%5B%22CTA%20%E5%8D%A0%E6%BB%A1%20SM%22%5D%0A%20%20CTA%20--%3E%20Q%7B%22%E8%AE%BE%E5%A4%87%E9%98%9F%E5%88%97%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%96%E4%B8%8B%E4%B8%80%20tile%20%2F%20%E4%B8%8B%E4%B8%80%E5%B1%82%22%7C%20WORK%5B%22TMA%20%2B%20MMA%20%2B%20epilogue%22%5D%0A%20%20WORK%20--%3E%20Q%0A%20%20Q%20--%3E%7C%22%E7%A9%BA%20%2F%20%E5%81%9C%E6%AD%A2%E6%A0%87%E5%BF%97%22%7C%20END%5B%22%E6%A0%B8%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<h3 id="与-warp-特化、流水的组合" tabindex="-1">与 warp 特化、流水的组合 <a class="header-anchor" href="#与-warp-特化、流水的组合" aria-label="Permalink to &quot;与 warp 特化、流水的组合&quot;">​</a></h3><p>Hopper 上持久化 CTA 内部往往仍是 <a href="/llm/warp-specialization">warp 特化</a> 加 <a href="/llm/sw-pipeline-buffer">软件流水</a>：常驻解决的是<strong>工作项之间</strong>不断流，特化解决的是<strong>一项内部</strong>拷贝与 MMA 重叠。不要用持久化替代 TMA 流水——队列再快，块内若同步搬砖，屋顶线还在。CUTLASS 3.x 的 Hopper 主循环把三者做成可组合的 kernel adapter：调度器（persistent 与否）在核入口，集体主循环在内层。</p><p>服务侧还要考虑与连续批处理的接口。若每步 batch 形状变，持久核必须能从固定缓冲读到当前形状，或在步边界结束核、下一步再 launch。把「永远不退出的核」和「每步换拓扑」绑在一起，会把动态调度全部塞进设备侧，调试成本通常高于收益。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收益来自保持 SM 的热状态：指令缓存、MMA 流水、已经填好的 pipeline stage、以及（在允许时）不重复做的预热拷贝。对短工作项，这些固定成本被摊到多次消费上。对已经很长的 prefill GEMM，一次核已经占满墙钟，持久化几乎无增益，甚至因调度器少了灵活超订而略差。</p>',5)),(r(),s(p,null,{default:a(()=>[n(l,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20NORM%5B%22%E6%99%AE%E9%80%9A%E7%BD%91%E6%A0%BC%EF%BC%9A%E6%AF%8F%E6%A0%B8%E4%B8%80%E6%AC%A1%20launch%22%5D%0A%20%20%20%20N1%5B%22%E5%A1%AB%EF%BC%9A%E6%8C%87%E4%BB%A4%E7%BC%93%E5%AD%98%E4%B8%8E%E6%B5%81%E6%B0%B4%E4%BB%8E%E9%9B%B6%E7%83%AD%E8%B5%B7%22%5D%20--%3E%20N2%5B%22%E5%81%9A%E4%B8%80%E5%B0%8F%E5%9D%97%E5%B7%A5%E4%BD%9C%22%5D%0A%20%20%20%20N2%20--%3E%20N3%5B%22%E6%8E%92%EF%BC%9A%E7%8E%B0%E5%9C%BA%E5%85%A8%E9%83%A8%E4%B8%A2%E5%BC%83%22%5D%0A%20%20%20%20N3%20--%3E%20N4%5B%22%E4%B8%8B%E4%B8%80%E4%B8%AA%E6%A0%B8%E5%86%8D%E4%BB%8E%E9%9B%B6%E7%83%AD%E8%B5%B7%22%5D%0A%20%20end%0A%20%20subgraph%20PERS%5B%22%E6%8C%81%E4%B9%85%E6%A0%B8%22%5D%0A%20%20%20%20P1%5B%22%E5%B8%B8%E9%A9%BB%20CTA%20%E4%BF%9D%E6%8C%81%E7%83%AD%E7%8A%B6%E6%80%81%22%5D%20--%3E%20P2%5B%22%E4%BB%8E%E9%98%9F%E5%88%97%E5%8F%96%E4%B8%8B%E4%B8%80%E5%B7%A5%E4%BD%9C%E9%A1%B9%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%22%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%E6%91%8A%E5%88%B0%E5%A4%9A%E9%A1%B9%E5%B7%A5%E4%BD%9C%E4%B8%8A%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p><span class="marginnote">直觉类比：普通 launch 像每炒一道菜都重新生一炉火、炒完就熄——火候永远是凉的；持久核像灶火一直不熄，厨师做完一道菜回队列领下一单。但灶火一直占着，别的订单（其他流）也插不进来——这就是尾部延迟变差的代价。</span></p><p>正确性依赖于工作项划分无重叠、规约有明确所有者。Stream-K 的部分和要写到指定缓冲再做一次归约核或核内协作归约；持久化不自动处理这部分。原子队列要避免所有 CTA 打同一 cache line：可以用每 SM 私有的工作范围，或条带化 tile 编号。争用严重时，持久化的墙钟会差过「普通网格一次 launch」。</p><p><span class="marginnote">持久核把 GPU 变成一台拉模型的工作机，主机变成填队列的生产者。CPU 若填得比消费慢，SM 空转在轮询上，功耗与延迟都差。队列项应足够粗（一整块 GEMM tile 或一整层），不要按标量任务投喂。</span></p><h3 id="和-cuda-graph-怎么选" tabindex="-1">和 CUDA Graph 怎么选 <a class="header-anchor" href="#和-cuda-graph-怎么选" aria-label="Permalink to &quot;和 CUDA Graph 怎么选&quot;">​</a></h3><p>Graph：拓扑固定、多个<strong>不同</strong>核、要减 CPU 提交。Persistent：同一套 CTA 代码、多个<strong>同类</strong>工作项、要减 GPU 排水。Decode 一步若是「RMSNorm 核 + GEMM 核 + 注意力核」三种代码，Graph 更自然；若已融合成一个大核反复吃层，持久化更自然。二者可叠：Graph 的一个节点是持久核。先用 profiler 看间隙在 CPU launch 还是在 GPU 核间空闲，再加其中一个，避免两套状态机同时上。</p><p><span class="marginnote">常见误区：把「少 launch」本身当成收益来源。Graph 少的是 CPU 提交次数，持久核少的是 GPU 核间的排水与预热——省的不是同一种时间。先看 profiler：间隙在 CPU 提交就上 Graph，在 GPU 核间空闲才轮到持久化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在多租户 MPS 上默认常驻占满 SM，除非理解对邻居延迟的影响，见 <a href="/llm/mps-mig">MPS 与 MIG</a>。不要让持久核内出现可阻塞的设备侧等待（无超时地等主机旗标），否则整卡卡死难以取消。不要把 NCCL 调用塞进持久循环却不核对图/流语义。取消与超时应走主机停止标志 + 有限轮询间隔，并在文档里写清最坏唤醒时间。</p><p>占用计算要用实际寄存器与 smem，含 pipeline stage。复制 CUTLASS 示例的 grid 到自己更大的 tile 上，可能每 SM 驻不下，网格空转。数值上，持久化改变 tile 被处理的顺序（尤其 stream-K），浮点尾差会变，应对照非持久路径设容差。</p><p><span class="marginnote">出处：CUTLASS 文档的 persistent CTA / stream-K 调度；CUDA Occupancy 与 launch 配置；Hopper 白皮书提供异步主循环为何值得跨 tile 保持常驻。CUDA Graph 指南说明二者解决的提交层不同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Persistent kernel 用常驻 CTA 从设备队列拉多次工作，减少核间排水与重复启动。</li><li>与 grid-stride 的差别是网格钉在 SM 占用上，循环跨逻辑任务而不是一次扫完就退出。</li><li>适合短而重复的同类工作；大 prefill GEMM 与高度动态的拓扑收益有限。</li><li>块内仍要靠 TMA / WGMMA / 流水打屋顶线；持久化不替代融合。</li><li>与 Graph 按瓶颈选择或叠加；注意多租户占用与取消语义。</li><li>出处：CUTLASS 持久化调度与 CUDA 占用率模型。</li></ul>',12))])}const S=E(B,[["render",d]]);export{u as __pageData,S as default};
